//
// The store keeps only the hash of the token (Hash) and its last four characters (Last4). Token is set only on the copy
// returned by the call that creates the key; it is never stored, snapshotted or listed.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
