	}
}

args.new_string:
// TouchAPIKey records that a key was used. It writes the time at most once a minute per key: a use less than a minute
// after the recorded one leaves it unchanged.
func (s *Store) TouchAPIKey(id string, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || (k.LastUsedAt != nil && now.Sub(*k.LastUsedAt) < apiKeyTouchInterval) {
		return
	}
	t := now.UTC()
	k.LastUsedAt = &t
	s.apiKeys[id] = k
}

