// apiKeyView is an API key as the API shows it. It never has the token or its hash.
type apiKeyView struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Last4      string     `json:"last4"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

func viewAPIKey(k store.APIKey) apiKeyView {
	return apiKeyView{ID: k.ID, OrgID: k.OrgID, UserID: k.UserID, Name: k.Name, Last4: k.Last4, CreatedAt: k.CreatedAt,
		LastUsedAt: k.LastUsedAt, RevokedAt: k.RevokedAt}
}

// createdAPIKey is a new API key with its token. The token is shown only in the answer that creates the key.
type createdAPIKey struct {
	apiKeyView
	Token string `json:"token"`
}

func newCreatedAPIKey(k store.APIKey) createdAPIKey {
	return createdAPIKey{apiKeyView: viewAPIKey(k), Token: k.Token}
}

func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []apiKeyView{}
	for _, k := range s.store.APIKeys(p.OrgID) {
		items = append(items, viewAPIKey(k))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

func (s *Server) createAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name string `json:"name"`
	}
	if !decode(w, r, &in) {
		return
	}
	k, err := s.store.CreateAPIKey(p.OrgID, p.UserID, in.Name, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, newCreatedAPIKey(k))
}

