func TestTouchAPIKeyWritesAtMostOncePerMinute(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "k", t0)

	s.TouchAPIKey(k.ID, t0)
	if got, _ := s.APIKey(o.ID, k.ID); got.LastUsedAt == nil || !got.LastUsedAt.Equal(t0) {
		t.Fatalf("first use: %+v", got.LastUsedAt)
	}
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if got, _ := s.APIKey(o.ID, k.ID); !got.LastUsedAt.Equal(t0) {
		t.Fatalf("a use 59 seconds later changed last use to %v", got.LastUsedAt)
	}
	s.TouchAPIKey(k.ID, t0.Add(time.Minute))
	if got, _ := s.APIKey(o.ID, k.ID); !got.LastUsedAt.Equal(t0.Add(time.Minute)) {
		t.Fatalf("a use a minute later left last use at %v", got.LastUsedAt)
	}
}

